package com.filemind.workspace.service;
import com.filemind.collaboration.entity.*; import com.filemind.collaboration.repository.DocumentAccessRepository; import com.filemind.common.exception.*; import com.filemind.document.entity.Document; import com.filemind.document.repository.DocumentRepository; import com.filemind.user.entity.User; import com.filemind.user.repository.UserRepository; import com.filemind.workspace.entity.*; import com.filemind.workspace.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.util.*;
@Service @RequiredArgsConstructor public class WorkspaceFolderService {
 private final FolderRepository folders; private final FolderAccessRepository accesses; private final FolderDocumentRepository folderDocuments; private final UserRepository users; private final DocumentRepository documents; private final DocumentAccessRepository documentAccesses;
 public List<Map<String,Object>> list(User u){var a=accesses.findAll();return folders.findAll().stream().filter(f->f.getOwner().getId().equals(u.getId())||f.isPublicFolder()||a.stream().anyMatch(x->x.getFolder().getId().equals(f.getId())&&x.getUser().getId().equals(u.getId())&&status(x)==FolderAccessStatus.ACTIVE)).map(f->view(f,u,a)).toList();}
 public Map<String,Object> create(User u,String name,boolean pub){if(name==null||name.isBlank())throw new BadRequestException("Folder name is required");WorkspaceFolder f=new WorkspaceFolder();f.setName(name.trim());f.setOwner(u);f.setPublicFolder(pub);f=folders.save(f);return view(f,u,List.of());}
 public Map<String,Object> setPublic(User u,String id,boolean pub){WorkspaceFolder f=owned(u,id);f.setPublicFolder(pub);return view(folders.save(f),u,accesses.findAll());}
 public Map<String,Object> share(User actor,String id,String email,String raw){WorkspaceFolder f=owned(actor,id);User target=users.findByEmailIgnoreCase(email==null?"":email.trim()).orElseThrow(()->new BadRequestException("That user must register with FileMind before they can be invited"));if(target.getId().equals(actor.getId()))throw new BadRequestException("The owner already has full access");FolderAccess a=accesses.findAll().stream().filter(x->x.getFolder().getId().equals(id)&&x.getUser().getId().equals(target.getId())).findFirst().orElseGet(FolderAccess::new);a.setFolder(f);a.setUser(target);a.setPermission(permission(raw));a.setStatus(FolderAccessStatus.PENDING);accesses.save(a);return view(f,actor,accesses.findAll());}
 public List<Map<String,Object>> requests(User u){return accesses.findAll().stream().filter(a->a.getUser().getId().equals(u.getId())&&status(a)==FolderAccessStatus.PENDING).map(a->Map.<String,Object>of("id",a.getId(),"folderId",a.getFolder().getId(),"folderName",a.getFolder().getName(),"ownerEmail",a.getFolder().getOwner().getEmail(),"permission",a.getPermission().name())).toList();}
 public void respond(User u,String accessId,boolean accepted){FolderAccess a=accesses.findById(accessId).orElseThrow(()->new ResourceNotFoundException("Access request not found"));if(!a.getUser().getId().equals(u.getId())||status(a)!=FolderAccessStatus.PENDING)throw new ForbiddenOperationException("You cannot respond to this request");if(!accepted){accesses.delete(a);return;}a.setStatus(FolderAccessStatus.ACTIVE);accesses.save(a);sync(a);}
 public Map<String,Object> updatePermission(User u,String folderId,String accessId,String raw){owned(u,folderId);FolderAccess a=access(folderId,accessId);a.setPermission(permission(raw));accesses.save(a);if(status(a)==FolderAccessStatus.ACTIVE)sync(a);return view(a.getFolder(),u,accesses.findAll());}
 public void remove(User u,String folderId,String accessId){owned(u,folderId);FolderAccess a=access(folderId,accessId);folderDocuments.findAll().stream().filter(fd->fd.getFolder().getId().equals(folderId)).forEach(fd->documentAccesses.findByDocumentIdAndUserId(fd.getDocument().getId(),a.getUser().getId()).ifPresent(documentAccesses::delete));accesses.delete(a);}
 public Map<String,Object> addDocument(User u,String folderId,String docId){WorkspaceFolder f=owned(u,folderId);Document d=documents.findByIdAndDeletedFalse(docId).orElseThrow(()->new ResourceNotFoundException("Document not found"));if(!d.getOwner().getId().equals(u.getId()))throw new ForbiddenOperationException("Only documents you own can be added");if(folderDocuments.findAll().stream().noneMatch(x->x.getFolder().getId().equals(folderId)&&x.getDocument().getId().equals(docId))){FolderDocument fd=new FolderDocument();fd.setFolder(f);fd.setDocument(d);folderDocuments.save(fd);accesses.findAll().stream().filter(a->a.getFolder().getId().equals(folderId)&&status(a)==FolderAccessStatus.ACTIVE).forEach(a->grant(d,a));}return view(f,u,accesses.findAll());}
 private void sync(FolderAccess a){folderDocuments.findAll().stream().filter(fd->fd.getFolder().getId().equals(a.getFolder().getId())).forEach(fd->grant(fd.getDocument(),a));} private void grant(Document d,FolderAccess a){DocumentAccess x=documentAccesses.findByDocumentIdAndUserId(d.getId(),a.getUser().getId()).orElseGet(DocumentAccess::new);x.setDocument(d);x.setUser(a.getUser());x.setPermission(a.getPermission());documentAccesses.save(x);}
 private WorkspaceFolder owned(User u,String id){WorkspaceFolder f=folders.findById(id).orElseThrow(()->new ResourceNotFoundException("Folder not found"));if(!f.getOwner().getId().equals(u.getId()))throw new ForbiddenOperationException("Only the folder owner can manage access");return f;} private FolderAccess access(String f,String id){return accesses.findById(id).filter(a->a.getFolder().getId().equals(f)).orElseThrow(()->new ResourceNotFoundException("Collaborator not found"));} private FolderAccessStatus status(FolderAccess a){return a.getStatus()==null?FolderAccessStatus.ACTIVE:a.getStatus();} private DocumentPermission permission(String raw){try{DocumentPermission p=DocumentPermission.valueOf(raw.trim().toUpperCase());if(p==DocumentPermission.OWNER)throw new BadRequestException("Use EDITOR or VIEWER");return p;}catch(Exception e){throw new BadRequestException("Permission must be EDITOR or VIEWER");}}
 private Map<String,Object> view(WorkspaceFolder f,User u,List<FolderAccess> all){boolean owner=f.getOwner().getId().equals(u.getId());var members=all.stream().filter(a->a.getFolder().getId().equals(f.getId())).map(a->Map.<String,Object>of("id",a.getId(),"email",a.getUser().getEmail(),"fullName",a.getUser().getFullName(),"permission",a.getPermission().name(),"status",status(a).name())).toList();var docs=folderDocuments.findAll().stream().filter(fd->fd.getFolder().getId().equals(f.getId())).map(fd->Map.<String,Object>of("id",fd.getDocument().getId(),"name",fd.getDocument().getName())).toList();return Map.of("id",f.getId(),"name",f.getName(),"public",f.isPublicFolder(),"ownerEmail",f.getOwner().getEmail(),"canManage",owner,"members",members,"documents",docs);}
}
